-- Read-only catalog inspection. Confirm the project before running.
begin read only;
select jsonb_build_object(
 'version',current_setting('server_version'),
 'relations',(select jsonb_agg(jsonb_build_object('name',c.relname,'kind',c.relkind,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'options',c.reloptions,'acl',c.relacl,
 'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'acl',a.attacl) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
 'privileges',(select jsonb_agg(jsonb_build_object('role',r.rolname,'select',has_table_privilege(r.oid,c.oid,'SELECT'),'insert',has_table_privilege(r.oid,c.oid,'INSERT'),'update',has_table_privilege(r.oid,c.oid,'UPDATE'),'delete',has_table_privilege(r.oid,c.oid,'DELETE'),'any_column_select',has_any_column_privilege(r.oid,c.oid,'SELECT'))) from pg_roles r where r.rolname in ('anon','authenticated','service_role'))))
 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('profiles_visible','profiles_blocked','channels_public','channel_invitations_sent','channel_invitations_received','message_media_public','profiles','user_settings','user_blocks','contacts','channels','channel_invitations','channel_admins','channel_followers','file_uploads','messages','stories','chats','chat_members')),
 'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename in ('profiles','user_settings','user_blocks','contacts','channels','channel_invitations','channel_admins','channel_followers','file_uploads','messages','stories','chats','chat_members')),
 'memberships',(select jsonb_agg(jsonb_build_object('role',r.rolname,'member',m.rolname,'inherit',am.inherit_option,'set',am.set_option)) from pg_auth_members am join pg_roles r on r.oid=am.roleid join pg_roles m on m.oid=am.member),
 'api_settings',(select jsonb_agg(jsonb_build_object('role',coalesce(r.rolname,'all'),'database',coalesce(d.datname,'all'),'setting',v)) from pg_db_role_setting s left join pg_roles r on r.oid=s.setrole left join pg_database d on d.oid=s.setdatabase cross join lateral unnest(s.setconfig) v where v like 'pgrst.db_schemas=%' or v like 'pgrst.db_extra_search_path=%'),
 'view_dependencies',(select jsonb_agg(distinct jsonb_build_object('view',v.relname,'target',pg_describe_object(d.refclassid,d.refobjid,d.refobjsubid))) from pg_class v join pg_rewrite rw on rw.ev_class=v.oid join pg_depend d on d.classid='pg_rewrite'::regclass and d.objid=rw.oid where v.relnamespace='public'::regnamespace and v.relname in ('profiles_visible','profiles_blocked','channels_public','channel_invitations_sent','channel_invitations_received','message_media_public')),
 'view_dependents',(select jsonb_agg(distinct jsonb_build_object('view',v.relname,'dependent',pg_describe_object(d.classid,d.objid,d.objsubid))) from pg_class v join pg_depend d on d.refclassid='pg_class'::regclass and d.refobjid=v.oid where v.relnamespace='public'::regnamespace and v.relname in ('profiles_visible','profiles_blocked','channels_public','channel_invitations_sent','channel_invitations_received','message_media_public'))
) as inventory;
commit;
